  return withDatabase(async (db) => { const tx = db.transaction("scores", "readwrite"); const store = tx.objectStore("scores"); deleteIds.forEach((id) => store.delete(id)); records.forEach((record) => store.put(record)); await done(tx); return records; }, indexedDb);
